function validate([n, connections]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is a whole number from 1 to 10^4.';
  if (!Array.isArray(connections) || connections.length < 1 || connections.length > 10000) return 'connections needs 1 to 10^4 roads.';
  for (const road of connections) {
    if (!Array.isArray(road) || road.length !== 3 || !road.every(Number.isInteger)) return 'Each road is [x, y, cost] with whole numbers.';
    const [x, y, cost] = road;
    if (x < 1 || x > n || y < 1 || y > n) return 'Road ends must be cities from 1 to n.';
    if (x === y) return 'A road must join two different cities.';
    if (cost < 0 || cost > 100000) return 'Each cost is between 0 and 10^5.';
  }
  return null;
}

