function minimumCost(n, connections) {
  const parent = Array.from({ length: n + 1 }, (_, city) => city);
  const find = (city) => {
    while (parent[city] !== city) {
      parent[city] = parent[parent[city]];
      city = parent[city];
    }
    return city;
  };

  const edges = [...connections].sort((a, b) => a[2] - b[2]);
  let total = 0;
  let groups = n;

  for (const [x, y, cost] of edges) {
    const rootX = find(x);
    const rootY = find(y);
    if (rootX === rootY) {
      continue;
    }
    parent[rootX] = rootY;
    total += cost;
    groups--;
    if (groups === 1) {
      return total;
    }
  }
  return groups === 1 ? total : -1;
}

