function minimumCost(n, connections) {
  const cheapest = Array.from({ length: n + 1 }, () => Array(n + 1).fill(Infinity));
  for (const [x, y, cost] of connections) {
    cheapest[x][y] = Math.min(cheapest[x][y], cost);
    cheapest[y][x] = cheapest[x][y];
  }
  const inTree = Array(n + 1).fill(false);
  const link = Array(n + 1).fill(Infinity);
  link[1] = 0;
  let total = 0;
  for (let step = 0; step < n; step++) {
    let pick = -1;
    for (let city = 1; city <= n; city++) {
      if (!inTree[city] && (pick === -1 || link[city] < link[pick])) pick = city;
    }
    if (link[pick] === Infinity) return -1;
    inTree[pick] = true;
    total += link[pick];
    for (let city = 1; city <= n; city++) {
      if (!inTree[city] && cheapest[pick][city] < link[city]) link[city] = cheapest[pick][city];
    }
  }
  return total;
}

