function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1000, 1900) : int(2, 7);
  const maxCost = large ? 100000 : rand() < 0.5 ? 6 : 100000;
  const total = large ? 2000 : int(1, 12);
  const connections = [];
  const pushEdge = (x, y) => connections.push([x, y, int(0, maxCost)]);
  // Usually lay down a random spanning tree first so the cities can be connected.
  if (rand() < 0.7 && n - 1 <= total) {
    const order = Array.from({ length: n }, (_, i) => i + 1);
    for (let i = n - 1; i > 0; i--) {
      const j = int(0, i);
      [order[i], order[j]] = [order[j], order[i]];
    }
    for (let i = 1; i < n; i++) pushEdge(order[i], order[int(0, i - 1)]);
  }
  while (connections.length < total) {
    const x = int(1, n);
    let y = int(1, n - 1);
    if (y >= x) y++;
    pushEdge(x, y);
  }
  for (let i = connections.length - 1; i > 0; i--) {
    const j = int(0, i);
    [connections[i], connections[j]] = [connections[j], connections[i]];
  }
  return [n, connections];
}
